-- Issue #281 (Aurelle AI palace coup): one row per AI plot, its public Crisis Window and outcome. Plot recruitment is derived from the seed, never stored. Names are capped at 24 characters. Additive table only.
CREATE TABLE IF NOT EXISTS aurelle_coups ( id TEXT PRIMARY KEY, formed_at INTEGER NOT NULL, ruler_id TEXT NOT NULL CHECK(ruler_id IN ('ashgrove','thornwick','dunmere','stormhaven','redwren','oakhollow')), ruler_name TEXT NOT NULL CHECK(length(ruler_name) BETWEEN 1 AND 24), house TEXT NOT NULL CHECK(length(house) BETWEEN 1 AND 24), window_opened_at INTEGER, window_closes_at INTEGER, guard_pct_at_open INTEGER, great_lords_at_open INTEGER, resolved_at INTEGER, outcome TEXT CHECK(outcome IS NULL OR outcome IN ('succeeded','failed')), stability_at_close INTEGER, CHECK((window_opened_at IS NULL) = (window_closes_at IS NULL)), CHECK((resolved_at IS NULL) = (outcome IS NULL)), CHECK(outcome IS NULL OR outcome = 'failed' OR window_opened_at IS NOT NULL) );
CREATE INDEX IF NOT EXISTS idx_aurelle_coups_formed ON aurelle_coups(formed_at);
